import { subtotal } from "./cart.js";
import { percentOff, shippingFor } from "./discount.js";

// 券后总额 = 折扣后的金额 + 运费
export function checkoutTotal(lines, couponPercent) {
  const sub = subtotal(lines);
  const shipping = shippingFor(sub);
  const discounted = couponPercent ? percentOff(sub, couponPercent) : sub;
  return discounted + shipping;
}

import { cents } from "./money.js";

export function subtotal(lines) {
  return lines.reduce((sum, l) => sum + cents(l.unitPrice * l.qty), 0);
}
import { cents } from "./money.js";

export const FREE_SHIPPING_AT = cents(5000);
export const SHIPPING_FEE = cents(600);

export function percentOff(amount, percent) {
  if (percent < 0 || percent > 100) throw new RangeError("percent 必须在 0-100");
  return cents(Math.round(amount * (1 - percent / 100)));
}

export function shippingFor(amount) {
  return amount >= FREE_SHIPPING_AT ? cents(0) : SHIPPING_FEE;
}
export function cents(n) {
  if (!Number.isInteger(n)) throw new TypeError("cents 必须是整数（分）");
  return n;
}

